const net = require('net');
const ldap = require('ldapjs');
const crypto = require('crypto');

class CircuitBreaker {
  constructor(options = {}) {
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.state = 'CLOSED';
    this.failureCount = 0;
    this.lastFailureTime = null;
    this.successCount = 0;
  }

  async execute(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.resetTimeout) {
        this.state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit breaker is OPEN');
      }
    }
    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  onSuccess() {
    this.failureCount = 0;
    if (this.state === 'HALF_OPEN') {
      this.state = 'CLOSED';
    }
    this.successCount++;
  }

  onFailure() {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN';
    }
  }
}

class LDAPQueryNormalizer {
  constructor() {
    this.encodingMap = {
      '\\28': '(',
      '\\29': ')',
      '\\2a': '*',
      '\\5c': '\\',
      '\\00': '\x00'
    };
  }

  normalizeForCache(filter) {
    let normalized = filter.toLowerCase().trim();
    normalized = normalized.replace(/\s+/g, '');
    return normalized;
  }

  decodeEscapedChars(input) {
    let result = input;
    for (const [escaped, char] of Object.entries(this.encodingMap)) {
      result = result.split(escaped).join(char);
    }
    return result;
  }

  buildUserFilter(username, baseDN) {
    const sanitized = this.sanitizeInput(username);
    const filter = `(&(objectClass=person)(uid=${sanitized}))`;
    return { filter, baseDN };
  }

  sanitizeInput(input) {
    if (typeof input !== 'string') return '';
    return input
      .replace(/\\/g, '\\5c')
      .replace(/\*/g, '\\2a')
      .replace(/\(/g, '\\28')
      .replace(/\)/g, '\\29')
      .replace(/\x00/g, '\\00');
  }
}

class LDAPProxyServer {
  constructor(config) {
    this.config = config;
    this.breaker = new CircuitBreaker(config.circuitBreaker);
    this.normalizer = new LDAPQueryNormalizer();
    this.queryCache = new Map();
    this.server = net.createServer(this.handleConnection.bind(this));
  }

  async handleConnection(socket) {
    socket.on('data', async (data) => {
      try {
        const request = JSON.parse(data.toString());
        const response = await this.processRequest(request);
        socket.write(JSON.stringify(response));
      } catch (err) {
        socket.write(JSON.stringify({ error: err.message }));
      }
    });
  }

  async processRequest(request) {
    const { action, username, attributes } = request;

    if (action === 'lookup') {
      return this.lookupUser(username, attributes);
    } else if (action === 'authenticate') {
      return this.authenticateUser(username, request.password);
    }
    return { error: 'Unknown action' };
  }

  async lookupUser(username, attributes) {
    const { filter, baseDN } = this.normalizer.buildUserFilter(
      username, this.config.baseDN
    );

    const cacheKey = this.normalizer.normalizeForCache(filter);

    if (this.queryCache.has(cacheKey)) {
      return this.queryCache.get(cacheKey);
    }

    const resolvedFilter = this.resolveFilterForBackend(cacheKey);

    const result = await this.breaker.execute(() =>
      this.executeLDAPQuery(resolvedFilter, baseDN, attributes)
    );

    this.queryCache.set(cacheKey, result);
    return result;
  }

  resolveFilterForBackend(normalizedFilter) {
    return this.normalizer.decodeEscapedChars(normalizedFilter);
  }

  async executeLDAPQuery(filter, baseDN, attributes) {
    return new Promise((resolve, reject) => {
      const client = ldap.createClient({ url: this.config.ldapUrl });

      client.bind(this.config.bindDN, this.config.bindPassword, (err) => {
        if (err) return reject(err);

        const opts = {
          filter: filter,
          scope: 'sub',
          attributes: attributes || ['cn', 'mail', 'uid']
        };

        const entries = [];
        client.search(baseDN, opts, (err, res) => {
          if (err) return reject(err);
          res.on('searchEntry', (entry) => entries.push(entry.object));
          res.on('error', (err) => reject(err));
          res.on('end', () => {
            client.unbind();
            resolve({ entries });
          });
        });
      });
    });
  }

  async authenticateUser(username, password) {
    const lookupResult = await this.lookupUser(username, ['dn']);
    if (!lookupResult.entries || lookupResult.entries.length === 0) {
      return { authenticated: false, reason: 'User not found' };
    }

    const userDN = lookupResult.entries[0].dn;
    return this.breaker.execute(() => this.bindAsUser(userDN, password));
  }

  async bindAsUser(dn, password) {
    return new Promise((resolve, reject) => {
      const client = ldap.createClient({ url: this.config.ldapUrl });
      client.bind(dn, password, (err) => {
        client.unbind();
        if (err) resolve({ authenticated: false, reason: 'Invalid credentials' });
        else resolve({ authenticated: true });
      });
    });
  }

  listen(port) {
    this.server.listen(port, () => {
      console.log(`LDAP Proxy listening on port ${port}`);
    });
  }
}

const config = {
  ldapUrl: 'ldap://ldap.internal:389',
  baseDN: 'dc=company,dc=com',
  bindDN: 'cn=proxy,dc=company,dc=com',
  bindPassword: process.env.LDAP_BIND_PASSWORD || '',
  circuitBreaker: { failureThreshold: 5, resetTimeout: 30000 }
};

const proxy = new LDAPProxyServer(config);
proxy.listen(8389);

module.exports = { LDAPProxyServer, CircuitBreaker, LDAPQueryNormalizer };
